"""
Offline robust segment-aware signal reconstruction with endpoint-aligned output.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter, medfilt
except Exception:
    savgol_filter = None
    medfilt = None


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    cs = np.concatenate(([0.0], np.cumsum(x)))
    return (cs[window_size:] - cs[:-window_size]) / float(window_size)


def _finite_signal(x):
    if np.all(np.isfinite(x)):
        return x
    good = np.isfinite(x)
    if not np.any(good):
        return np.zeros_like(x)
    idx = np.arange(len(x))
    return np.interp(idx, idx[good], x[good])


def _median3(x):
    if len(x) < 3:
        return x.copy()
    if medfilt is not None:
        return medfilt(x, kernel_size=3)
    p = np.pad(x, (1, 1), mode="edge")
    return np.median(np.stack((p[:-2], p[1:-1], p[2:])), axis=0)


def _smooth_piece(piece):
    n = len(piece)
    clean = _median3(piece)
    if savgol_filter is None or n < 5:
        return clean
    frame = min(17, n if n % 2 else n - 1)
    if frame < 5:
        return clean
    order = min(3, frame - 2)
    return savgol_filter(clean, frame, order, mode="interp")


def enhanced_filter_with_trend_preservation(x, window_size=20):
    """Denoise with padded stationary-wavelet soft thresholding and increment hysteresis."""
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1:
        raise ValueError("window_size must be positive")
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )

    clean = np.asarray(_finite_signal(x), dtype=float).copy()
    n = len(clean)
    if n < 2:
        return clean[window_size - 1:].copy()

    try:
        import pywt
    except Exception:
        return np.asarray(_median3(clean), dtype=float)[window_size - 1:].copy()

    levels = min(4, int(np.floor(np.log2(n))))
    if levels < 1:
        return np.asarray(_median3(clean), dtype=float)[window_size - 1:].copy()

    block = 2 ** levels
    padded_length = int(np.ceil(n / block) * block)
    if padded_length > n:
        pad = padded_length - n
        left = pad // 2
        right = pad - left
        work = np.pad(clean, (left, right), mode="reflect")
    else:
        left = 0
        work = clean.copy()

    try:
        coeffs = pywt.swt(
            work,
            wavelet="db4",
            level=levels,
            trim_approx=False,
            norm=True,
        )
        finest = np.asarray(coeffs[-1][1], dtype=float)
        center = np.median(finest)
        sigma = 1.4826 * np.median(np.abs(finest - center)) + 1e-12
        base = sigma * np.sqrt(2.0 * np.log(max(len(work), 2)))

        thresholded = []
        for level_index, (approx, detail) in enumerate(coeffs):
            detail = np.asarray(detail, dtype=float)
            threshold = base / (2.0 ** (0.35 * level_index))
            shrunk = np.sign(detail) * np.maximum(
                np.abs(detail) - threshold, 0.0
            )
            thresholded.append((np.asarray(approx, dtype=float), shrunk))

        reconstructed = np.asarray(
            pywt.iswt(thresholded, wavelet="db4", norm=True),
            dtype=float,
        )
        reconstructed = reconstructed[left:left + n].copy()
    except Exception:
        return np.asarray(_median3(clean), dtype=float)[window_size - 1:].copy()

    deadband = 0.12 * sigma
    if n > 1 and deadband > 0.0:
        previous = reconstructed[0]
        for i in range(1, n):
            increment = reconstructed[i] - previous
            if abs(increment) < deadband:
                reconstructed[i] = previous
            else:
                previous = reconstructed[i]

    return reconstructed[window_size - 1:].copy()


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(
    noisy_signal=None, signal_length=1000, noise_level=0.3, window_size=20
):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:]
    aligned_noisy = noisy_signal[delay:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = (
        float(np.corrcoef(filtered_signal, aligned_clean)[0, 1]) if m > 1 else 0.0
    )
    before = np.var(aligned_noisy - aligned_clean)
    after = np.var(filtered_signal - aligned_clean)
    reduction = float((before - after) / before) if before > 0 else 0.0

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

